SY_TALK("UEZvd6z14Uo.hi",[[17,["सवेरे ४ बजे से ही काम शुरू हो जाता है उसके","बाद ख़तम होते होते आज घर से देर हो गयी है।"]],[27,["कल मैंने आपसे बताया था कि मैं आपको","कुण्डलिनी के बारे में बताऊँगी।"]],[31,["ये सबको दिखाई दे रहा है क्या चार्ट?"]],[33,["जिनको नहीं दिखाई दे रहा, इस तरह से बैठ","जायें - इधर आ जायें ज़रा, ठीक से बैठ जायें।"]],[38,["कृपया ये इधर आजाईए। जिनको नहीं दिखाई","दे रहा, ज़रा इधर सरक जायें।"]],[51,["[ENGLISH - यह दिखने जा रहे हैं (अस्पष्ट)]"]],[59,["श्री माता जी मराठी में कहते हैं “ हवा काफी","तेज है, ठीक है ना!” [अस्पष्ट बातचीत]"]],[65,["[अस्पष्ट बातचीत] हाँ"]],[81,["[अस्पष्ट बातचीत]"]],[89,["ज़रा बैठिये, अब आप देखिये, सामने बैठ","जाइये। हाँ, ठीक है।"]],[100,["एक तरफ चले आइये, एक ओर"]],[120,["मैंने आपसे कल बताया था कि मानव जिस","प्रकृति से बना है उस प्रकृति ने अपने अंदर"]],[132,["बड़े कमाल के काम कर रखे हैं और इसी","कारण हम बनाये गए हैं।"]],[140,["जो अब बात कहने वाली हूँ उसके बारे में हमारे आज के","जो आधुनिक शास्त्र हैं इसमें कोई विवरण नहीं है।"]],[156,["जैसे कि मैंने बताया था कि आजकल के आधुनिक","शास्त्र, जो कुछ भी इस दृष्टि को गोचर होता है,"]],[163,["जो भी इस दृष्टि से देखा जाता है साक्षात,","उसे ही जानते हैं और यह जो दृष्टि मानव की है,"]],[170,["इसमें अभी आत्मा का प्रकाश नहीं आया है","- मनुष्य अभी प्रबुद्ध नहीं हुआ।"]],[175,["प्रबुद्ध होने के बाद ही वो सब चीज़ें जो","मैं बता रही हूँ, वो यहाँ हैं।"]],[181,["यह चीज़ें हमारे अंदर हैं या नहीं, यह भी आप","लोग ख़ुद अपनी आँख से भी देख सकते हैं।"]],[190,["पहली तो चीज़ यह है कि मानव पहले स्थित","होता है, उसका अस्तित्व बनता है।"]],[197,["सारी सृष्टि की भी पहले स्थिति बनती है। अगर","उसकी स्थिति न बने तो हो ही नहीं।"]],[208,["ये जो स्थिति बनती है, यह हमारे अन्दर जो","परमात्मा की शक्ति है, उसकी  वजह से बनती है"]],[217,["उस शक्ति को हम लोग सदाशिव की शक्ति","कहते हैं या शिव की शक्ति कहते हैं।"]],[227,["इस शक्ति से हमारा अस्तित्व बनता है (एक्सिस्टेंस)।","इस शक्ति का नाम ऋषि मुनियों ने","महाकाली दिया था।"]],[243,["यह शक्ति हमारे अन्दर राइट साइड से गुज़र कर","लेफ्ट साइड को निकल आती है।"]],[251,["जैसे कि यहाँ दिखाया गया है - (आप दिखाइए,","इड़ा नाड़ी का पथ, इधर आओ, यह , वह दिखाओ )"]],[266,["इसे वहन करने वाली जो नाड़ी है, जो","चैनल है, उसे इड़ा नाड़ी कहते हैं।"]],[273,["अब यह सब चीज़ें जो हैं, ये सूक्ष्म चीज़ें हैं, सटल","चीज़ें हैं, यह बाह्य में दिखाई नहीं देतीं"]],[280,["लेकिन इसी नाड़ी से हमारे अन्दर जो लेफ्ट","सिम्पैथेटिक नर्वस सिस्टम (बायाँ अनुकंपी","तंत्रिका तंत्र) है"]],[286,["उसका प्रादुर्भाव होता है वो मैनिफेस्ट होता है","- लेफ्ट सिम्पैथेटिक नर्वस सिस्टम।"]],[294,["इसी प्रकार जैसे कि स्थिति होती है, जिस तरह से","हमारा अस्तित्व होता है, अस्तित्व का न रहने पे","हम मृत्यु को प्राप्त होते हैं।"]],[312,["इसका मतलब यह है कि, यही शक्ति जब नष्ट","हो जाती है, तो हमारा संहार हो जाता है।"]],[318,["इसी लिए इसे बहुत से लोग संहार शक्ति","के नाम से भी जानते हैं।"]],[323,["जैसे जब सूर्य लय हो जाता है तो अंधकार","हो जाता है, उसी प्रकार इसका।"]],[330,["जैसे कि, एक शक्ति का न होना और होना,","दोनों एक ही शक्ति का द्योतक है,"]],[335,["इस शक्ति को स्थिति और लय, दोनों","के ही द्योतक कहना चाहिए।"]],[346,["दूसरी जो शक्ति हमारे अन्दर विचरण करती है,","जिससे कि हम सृजन करते हैं, क्रिएट करते हैं,"]],[361,["जिससे हम सोचते हैं, जिससे शरीर की धारणा","करते हैं, शरीर को हम चलायमान रखते हैं,"]],[370,["इस शक्ति को ब्रह्मदेव की शक्ति कहते हैं और इस","ब्रह्मदेव की शक्ति का नाम है महासरस्वती।"]],[381,["यह शक्ति हमारे - (मैं इसलिए अंग्रेजी में कह रहीं हूँ","कि हिंदी भाषा में इससे कन्फूशन हो जाता है","लेफ्ट साइड से) -"]],[390,["यह हमारी लेफ्ट साइड से गुज़र के और","राइट साइड मैं आ जाती है।"]],[398,["यह शक्ति वहन करने वाली जो नाड़ी है, जो","सूक्ष्म नाड़ी है, अति सूक्ष्म नाड़ी है, इसे पिंगला नाड़ी","कहते हैं।"]],[406,["जो पहली नाड़ी है उसे चंद्र नाड़ी भी कहते हैं","और इसे सूर्य नाड़ी भी कहते हैं।"]],[415,["इस नाड़ी से हमारे अन्दर राइट सिम्पैथेटिक","नर्वस सिस्टम (दायाँ अनुकंपी तंत्रिका तंत्र) -"]],[423,["ये तो सूक्ष्म नाड़ी है लेकिन जो जड़ नाड़ी है, जो","आँखों में को दिखाई देती है, और जो कार्यान्वित है,"]],[432,["वो राइट सिम्पैथेटिक नर्वस सिस्टम","उसका प्रादुर्भाव है।"]],[437,["इस नाड़ी से, मैंने आपसे बताया, कि हम शारीरिक","कार्य तथा मानसिक कार्य, जिससे हम सोचते हैं,","विचारते हैं, वो होता है।"]],[446,["पहली जो नाड़ी है, जिसे हम चंद्र नाड़ी कहते हैं या इड़ा","नाड़ी कहते हैं, इससे हमारा सुप्त चेतन कार्यान्वित","रहता है, जिसे सबकॉन्ससियस (अचेतन) कहते हैं","लोग।"]],[459,["जैसे आज आप मेरी बातचीत सुन रहे हैं, इस वक्त","आप वर्तमान में मेरी बात सुनते हैं और फ़ौरन","उसे सुप्तचेतन में डाल देते हैं।"]],[468,["कॉन्ससियस माइंड से आप सुन रहे हैं और","कॉन्ससियस माइंड से आप सबकॉन्ससियस में","इसे डाल देते हैं।"]],[474,["और इसी, इसी मन की वजह से","आपके अन्दर संस्कार होते हैं -"]],[480,["चाहे वह सुसंस्कार हों, चाहे वो कुसंस्कार हों,","जिससे कंडीशनिंग ऑफ़ द ब्रेन होता है।"]],[486,["इसी से हमारा गत होता है, भव होता है माने जो कुछ","हमारी बीत गयी, पास्ट, वो होता है - जिसे हम","भूतकाल कहते हैं।"]],[502,["सारा जो कुछ बीत गया है, वह हमारे इसी","नाड़ी के कारण संग्रहित होते रहते हैं।"]],[510,["और उसी का बहुत ही अति सूक्ष्म रिकॉर्डिंग","या संकलन इस कुण्डलिनी में होता है।"]],[522,["कुण्डलिनी शक्ति, यह महाकाली","शक्ति का ही अवशेष है।"]],[529,["सदाशिव की शक्ति जो है यह हमेशा स्थित है,","जैसे कि एक बीज होता है। इसी बीज में से यह","दोनों शक्तियाँ जागृत होतीं हैं"]],[541,["और अंत में इसी में लय हो जातीं हैं और","इसीलिए उसे सदाशिव कहते हैं।"]],[549,["क्योंकि वो शक्ति हमेशा स्थित रहती है, उसमें से","दूसरी शक्तियाँ जागृत हो करके फिर उसी में","लयमान हो जातीं हैं।"]],[560,["इसके अलावा बीचों बीच हमारे अन्दर एक और","शक्ति निहित है जिसे वहन करने वाली नाड़ी को","सुषुम्ना नाड़ी"]],[575,["ऐसे कहते हैं - कोई सुषुम्ना कहते हैं कोई (अस्पष्ट)","कहते हैं तरह तरह से इसके प्रोनन्सिएशन्स हैं लेकिन"]],[581,["सुषुम्ना इसका सही माने में प्रोनन्सिएशन है","जो कि आप मंत्र में भी उच्चारण कर पायेंगे।"]],[590,["यह सुषुम्ना नाड़ी जो है यह वहन करती है हमारी","उत्क्रांति की सीढ़ी - एवोलुशनरी प्रोसेस।"]],[603,["इसी नाड़ी के कारण हम अमीबा से इंसान बने हैं।"]],[609,["इन तीनों नाड़ियों से भी जो कुछ घटित होता है,","जो कुछ बन पड़ता है, जो कुछ जीव हासिल करता है,"]],[625,["जो कुछ पाता है, वह हमारे सेंट्रल नर्वस सिस्टम","(केंद्रीय तंत्रिका तंत्र) पे रहता है, जो पीछे की ओर","हमारे दिमाग से नीचे की ओर उतरती है।"]],[637,["आज जो मानव की चेतना है, जैसे आज आप हैं,","वास्तविक में जो आपने पाया हुआ है, वो आपके"]],[644,["सेंट्रल नर्वस सिस्टम में, आपके कॉन्ससियस","माइंड में, पूरी तरह से स्थित है।"]],[650,["इस प्रकार मैंने आपको चार संस्थाओं","के बारे में बताया है।"]],[657,["जो मध्यवर्गी संस्था है, इसको हम","श्री विष्णु की संस्था कहते हैं।"]],[667,["श्री विष्णु की शक्ति से पहले तो धर्म की धारणा होती","है। धर्म की धारणा से ही उत्थान बनते जाता है।"]],[676,["जैसे कि एक आप केमिस्ट्री (रसायन विज्ञान) का","पीरियाडिक टेबल देखें, तो आप समझ सकते हैं"]],[685,["कि किस ख़ूबी से सारे जितने भी एलिमेंट्स हैं उनको","परमात्मा ने किस ख़ूबी से उनको व्यवस्थित","रूप से रचा है।"]],[697,["और उसकी अलग अलग शक्ति कहिये या","धर्म धारणा उन लोगों की भी है।"]],[708,["उनके आठ वैलेन्सीस होतीं हैं और यह सब कुछ","आप किसी भी मेडिकल या किसी भी केमिस्ट्री वाले","से पूछ सकते हैं।"]],[715,["और यह आठ वैलेंसीइस में से, किसी के पास में","चार होती हैं पूरी या आठ पूरी होतीं हैं जो संपूर्ण होते हैं,"]],[722,["और किसी के पास एक या दो हो जातीं हैं की कमी","या ज़्यादती होने के कारण ही उनका जो कुछ भी","व्यवहार है वो होते रहता है।"]],[731,["यह बहुत ही ख़ूबी से बनाई हुई चीज़ है। यह भी धारणा,","यह भी धर्म धारणा, यह भी विष्णु तत्व से ही होता है।"]],[741,["जैसे कि सोने की धर्म धारणा है कि वो कभी भी ख़राब","नहीं होता है, काला नहीं होता है, अनटार्निशिबिल है।"]],[751,["यह भी धर्म धारणा विष्णु तत्व से होती है।","यह विष्णु तत्व हमारे अंदर नाभि पर जागृत है।"]],[763,["जब यह तत्व ख़राब हो जाता है, तब","हमारी उत्क्रांति रुक जाती है।"]],[771,["यही तत्व हमें अधिकतर सहज योग में व्यव्हार में","लाना है और इसी के बारे में हमें ज़्यादा विचारणा","करनी होगी।"]],[782,["मैंने आपसे पहले बताया है, कि कुण्डलिनी जो है, यह","महाकाली की शक्ति का अवशेष या रेसिडुअल पार्ट है।"]],[791,["इसमें जो कुछ हमने आजतक किया हुआ है, जो","गलतियाँ की हों, जो पुण्य सम्पदा की हो,"]],[797,["जिस तरह से भी हमने जो कुछ पाया हुआ है, जो भी थे","हमारे संस्कार, चाहे कुसंस्कार हों, चाहे सुसंस्कार हों,"]],[804,["हर कुछ, हमारी बीमारियाँ, हमारी तक़लीफ़ें इस जन्म","और अनेक जन्मों की, सारी की सारी इसमें सब","टेपड हैं।"]],[814,["और यही आपकी माँ है जो यह सारे सुसंस्कार अपने","अंदर समाये हुए है आपके साथ विचरण करती है"]],[821,["इसीलिए हम इसे सहज योग कहते हैं। लेकिन यह","आपके त्रिकोणाकार अस्थि में साढ़े तीन कुण्डलों में","स्थित होती है।"]],[832,["यह साढ़े तीन क्यों (अस्पष्ट) है वगैरह का भी बड़ा","भारी गणित है पर उत्तर भी मैं बोलने लगूँ तो","(अस्पष्ट) तो गणित का।"]],[845,["ये कुण्डलिनी हमारे अंदर है या नहीं,","ये आप अपनी आँखों से देख सकते हैं।"]],[850,["जब कुण्डलिनी का जागरण होता है, तब आप देख","सकते हैं कि आपकी ये त्रिकोणाकार अस्थि में किस","प्रकार स्पंदित रहती है।"]],[861,["जब भी नाभि चक्र में पकड़ हो जाती है, तब","विशेषकर इसका स्पंदन इतनी ज़ोर से दिखाई देता है"]],[867,["कि एक छोटा बच्चा भी इसे देख ले। इसके","लिए कोई भी प्रमाण की ज़रुरत नहीं।"]],[875,["इसकी हम लोगों ने फिल्म भी बनाई हुई है","जो हम बीबीसी से सब दिखाने वाले हैं।"]],[880,["कुण्डलिनी यहीं पर स्थित होती है","और किसी जगह नहीं।"]],[883,["अब आप पढ़िए कोई कोई किताबें हैं - एक इरविन साहब","ने एक इतनी बड़ी किताब कुण्डलिनी की लिखी है।"]],[889,["उनको अभी तक यह भी पता नहीं एक्साक्ट्ली (सही","तरह से) कहाँ कुण्डलिनी हैं। फिर लिखते क्यों हो?"]],[893,["इतनी बड़ी किताब लिखने का उनको किसने अधिकार","दिया? क्योंकि वो अँगरेज़ हो गए इसका मतलब ये","थोड़ी है कि आप जो चाहें सो लिखें ?"]],[902,["किताबें पढ़ पढ़ के और अनुभव के बगैर, देखे बगैर ही","उन्होंने लिख दिया कि कुण्डलिनी शायद पेट में होती है"]],[909,["और या तो (अस्पष्ट) में शायद उससे कुछ नीचे","होती है और या तो सीट पर होती है।"]],[917,["परमात्मा की जितनी भी चीज़ बनाई हुई है उसमें","इतना सा भी इधर उधर नहीं होता है -","सत्य एक ही होता है।"]],[925,["यह सब कन्फूशन तो मनुष्य के दिमाग में अराइज","होते हैं। ये यहाँ है, कि वहां है, कि ये है।"]],[930,["परमेश्वर ने जहाँ जो चीज़ बनाई वह वहीँ होगी और","कहीं नहीं होगी, यह आप अपनी आँख से देख सकते हैं।"]],[938,["यह त्रिकोणाकार अस्थि में बैठी हुई कुण्डलिनी अनेक","जन्मों से आपके साथ है विचरण करती है।"]],[946,["मृत्यु के बाद भी आप ही के सर पर मंडराती","रहती है और जैसे ही आप जन्म लेते हैं,"]],[951,["फिर से आप ही के अंदर प्रवेश करके","वहीँ स्थित हो जाती है।"]],[956,["मृत्यु होना और फिर से जन्म लेना ये भी","एक बड़ा भारी चयन का कार्य है।"]],[960,["उसके बारे में बताने के लिए एक","बड़ा भारी लेक्चर देना होगा।"]],[967,["लेकिन हमारा मृत्यु से कोई सम्बन्ध इस वक़्त नहीं है","- आज वर्तमान, प्रेसेंट से हमारा सम्बन्ध है और उसी","के बारे में हम बात करेंगे।"]],[977,["जैसे कि लेफ्ट साइड की इड़ा नाड़ी हमारे","सबकॉन्ससियस से मतलब रखती है, हमारे पास्ट","से मतलब रखती है,"]],[987,["उसी प्रकार राइट साइड की जो नाड़ी है, जिसे पिंगला","नाड़ी कहते हैं, वो हमारे फ्यूचर से सम्बन्ध रखती है,","भविष्य से सम्बन्ध रखती है।"]],[995,["और जो बीचो-बीच हमारी जो नाड़ी है वो,","आज से, वर्तमान से, इस क्षण से।"]],[1011,["इसके बीच में जो गैप है, जो आप देख रहे हैं, इसी","के कारण मनुष्य वर्तमान में नहीं रह सकता।"]],[1021,["या तो वह आगे रहता है या पीछे रहता है - बीचो-बीच","वर्तमान में नहीं रह सकता, प्रेसेंट में नहीं।"]],[1030,["अब कुण्डलिनी जागरण कैसा होता है वह देखिये।","जिस वक़्त आप मेरी ओर हाथ ऐसे करके बैठे हैं"]],[1037,["तब मेरे अंदर से जब ये शक्ति - वैसे भी बह रही है","- वो आपके हाथ से गुज़र के, क्योंकि उँगलियों में भी,"]],[1044,["आप देखिये वहाँ उँगलियों में इन्होंने दिखाया नहीं है,","लेकिन पिछले चार्ट पे हमने दिखाया था कि","इनमें भी चक्र हैं।"]],[1050,["राइट और लेफ्ट में, राइट हैंड में और लेफ्ट","हैंड में भी चक्र हैं और यह सारी उँगलियाँ,"]],[1056,["उँगलियों के जो किनारे हैं, जिसको कहना चाहिए कि","जो एड्जेस जिसे कहते हैं, इस जगह पर उन चक्रों का","स्थान है।"]],[1064,["और यह चक्र जब जागृत हो जाते हैं, तब आप","इनपे महसूस कर सकते हैं कि,"]],[1072,["आपके कौन से चक्र पकडे हैं और दूसरों के कौन","से पकडे हैं। इससे लेफ्ट सिम्पैथेटिक,"]],[1079,["और इससे राइट सिम्पैथेटिक, दोनों साइड के चक्र आप","इसपे जानते हैं और जब आप चक्रों को पकड़ लेते हैं"]],[1086,["तो आप कोई सी भी बीमारी चक्रों की","वजह से ठीक कर लेते हैं।"]],[1090,["जैसे कि एक कल लड़की आ रही थी मिर्गी की","बिलकुल अचानक ठीक हो गयी, बहुत अच्छे","से चलने-वलने लग गयी,"]],[1096,["उनको मल्टीप्ल स्क्लीरोसिस था जो कि इनक्योरइबल","है कोई नहीं ठीक कर सकता, वह सहजयोग से ठीक","क्यों हो ?"]],[1104,["वजह ये है कि इसमें तो पहले निदान होता है कि","कौन से चक्र पकडे हैं। मूलाधार चक्र पकड़ा हुआ है,","ह्रदय चक्र पकड़ा हुआ है।"]],[1111,["अगर आप मूलाधार चक्र पर श्री गणेश को जागृत","कर दें और ह्रदय चक्र में शिव को संतुष्ट कर दें ,"]],[1117,["तो फ़ौरन (अस्पष्ट - वहाँ विब्रेशन्स आ जायेंगे?)","क्योंकि उसके जो चक्र हैं, जो अंतर में हैं,"]],[1121,["जो उसके बेसिक हैं, उसको यहाँ पे अगर ठीक","कर दिया, तो आदमी ठीक हो जायेगा।"]],[1126,["डायग्नोसिस भी इंसान ही करता है उसमें। जो बाहर","आदमी हो जाता है, वह खुदी डायग्नोसिस करता है।"]],[1132,["वही ट्रीटमेंट देता है और वही दवा भी देता है और","वही दूसरे को पार भी करता है।"]],[1141,["जो सबसे पहला चक्र है, वह कुण्डलिनी के नीचे है।","इसे बहुत समझ के परमात्मा ने वहाँ रखा हुआ है।"]],[1149,["यह चक्र जो है, यह चक्र श्री गणेश के कारण शोभित","है। इस चक्र का नाम मूलाधार चक्र और उससे ऊपर","मूलाधार है।"]],[1173,["त्रिकोणाकार अस्थि को हम मूलाधार कहते हैं,","कोई लोग उसको कुम्भ-कुंड कहते हैं - दुनिया भर","के नाम दिए हुए हैं।"]],[1179,["पर मूलाधार चक्र में श्री गणेश जी रहते/बैठे हैं और","ये जो मूलाधार चक्र है, इसको समझ लेना बहुत बहुत","ज़रूरी है"]],[1191,["कि इसी से हमारा सेक्स भी संचालित रहता है","और ऊपर श्री गणेश को बिठा दिया।"]],[1199,["श्री गणेश एक अबोध बालक हैं इसलिए उनको वहाँ","बिठाया गया क्योंकि वह इतने पवित्रतम हैं,"]],[1207,["कि उन्हें कोई भी गँदगी नहीं छू सकती इसलिए उनको","बिठाया है। क्योंकि छोटे बालक में इतनी अबोधिता","होती है, कहना चाहिए,"]],[1216,["इनोसेंस होता है, कि वह इन सब चीज़ों से परे","होता है। इसलिए श्री गणेश को वहाँ बिठाया है।"]],[1223,["श्री गणेश वहाँ बैठकर जो कुण्डलिनी गौरी स्वरूपा हैं -","माने वह विवाहिता तो हैं पर अभी पति से मुलाकात","नहीं हुई -"]],[1233,["अभी वर्जिन हैं - विर्जिनिटी में ही उसने","अपने गणेश को बनाकर बिठाया हुआ है -"]],[1239,["देखिये कितनी सुन्दर उसकी व्यवस्था है और वह वहाँ","बैठीं हुईं हैं, पति के इंतज़ार में, शिव से मिलने के","इंतज़ार में,"]],[1249,["उसकी लज्जा रक्षा के लिए, उसके प्रोटोकॉल","के लिए, श्री गणेश वहाँ बिठाये हैं।"]],[1256,["अब इसपर मैं आपको यह बताऊँगी कि तांत्रिकों","ने क्या गलती कर दी।"]],[1260,["इस वजह से, कि मैं माँ हूँ, मैं यह नहीं कहूँगी कि","जान-बूझ करके उन्होंने यह काम किया क्योंकि यह","महापाप हो जायेगा।"]],[1267,["लेकिन ग़लती से ही हो सकता है कि, शुरुआत में जब","उन्होंने मनन शुरू किया, तो इतनी शुद्धता न होने के","कारण,"]],[1275,["हो सकता है, कि श्री गणेश की सूंड को ही उन्होंने","कुण्डलिनी समझा होगा और इस वजह"]],[1283,["कुण्डलिनी का स्थान इस जगह माना होगा जहाँ हम","लोग चक्र की धारणा करते हैं; जहाँ श्री गणेश हैं वहाँ","कुण्डलिनी नहीं है"]],[1291,["और इसीलिए उन्होंने ऐसी थ्योरी निकाली हो","कि सेक्स करने से कुण्डलिनी ऊपर चढ़ती है;","शुरुआत में शायद ऐसी ग़लती हो गयी हो।"]],[1300,["हो सकता है, क्योंकि माँ के रिश्ते में","मैं पूरी तरह से उनको दोष नहीं दूँगी।"]],[1305,["वो भी मेरे बच्चे ही हैं। लेकिन इससे बढ़के","कभी भी कोई भी गलती इंसान ने नहीं की।"]],[1312,["आप सोचिए कि कुण्डलिनी आपकी माँ है और","उसपे कितना बड़ा दोषारोपण हो रहा है।"]],[1322,["लेकिन इस ग़लती को लेकर सारा तांत्रिक","समाज तैयार हो गया। छठी सेंचुरी में,"]],[1329,["छठी शताब्दी में अपने देश में तो हाहाकार मचा","दिया तांत्रिकों ने और सारे राजे महाराजे"]],[1336,["जो कि गंदगी के बिलकुल मैले-कुचैले जीवन से","प्लावित थे, उन्होंने इसको और भी ज़्यादा शह दे देकर"]],[1345,["इतनी बुरी हालत कर दी, कि हमारे सारे शिल्प","कलाओं में, यहाँ तक कि हमारे शास्त्रों में"," व विज्ञान तक में दर्शाया गया।"]],[1353,["इन्होंने यहाँ तक कहना शुरू कर दिया कि शिव","और शक्ति यह भी सब समलैंगिक थे;"]],[1358,["और ऐसा कहना शुरू कर दिया कि","अश्वमेध यज्ञ भी एक समलैंगिक ही था।"]],[1364,["जिस आदमी की आँख सावन में अंधी हो","जाती है, उसको सब ही हरा दिखाई देता है।"]],[1372,["इतने ऊँचे पवित्रतम तत्व को उन्होंने लाकर","के बिलकुल मिट्टी में डाल दिया।"]],[1378,["तांत्रिक तो असल में हम हैं क्योंकि हम तंत्र को जानते","हैं और हम तंत्र चलाते हैं। यही आपका तंत्र है","जिसे कुण्डलिनी कहते हैं।"]],[1386,["लेकिन इन दुष्टों ने अपना नाम तांत्रिक रख लिया; यह","तो ऐसा हुआ कि कोई चोर आकर के कहे कि मैं राजा हूँ।"]],[1397,["और इसी दुविधा के कारण मनुष्य को यही नहीं","समझ में आता है कि कुण्डलिनी का नाम लेते ही,","माताजी पवित्रता की बात कैसे करतीं हैं।"]],[1405,["यह , दरअसल, कुण्डलिनी जो कि पवित्रतम चीज़ है","उसका सम्बन्ध पवित्रता से लगाने पे ही लोग चौंक","जाते हैं।"]],[1416,["कितना अँधकार है!"]],[1423,["फिर जब इस तरह के लोग जिनके जीवन में","चरित्र का कोई मतलब नहीं, जिनमें पावित्र्य नहीं,"]],[1430,["जो बुरी तरह से अपनी ज़िन्दगी बिता रहे हैं, जिन्होंने","अपने सर्वनाश की पूर्ण व्यवस्था कर ली है,"]],[1436,["ऐसे लोग कुण्डलिनी पर हाथ डालेंगे, तो ज़रूरी है कि","उनके अंदर गर्मी आएगी, उनका शार्ट सर्किट होएगा,"]],[1442,["आफतें आयेंगी, वो कूदेंगे और दुनिया भर की चीज़ें।"]],[1446,["ये अनुभव जिन जिन लोगों को आये हैं वह लाज़मी है","क्योंकि इस ग़लती के लिए श्री गणेश के कारण","सारा सिम्पैथेटिक वह ताड़ देते हैं।"]],[1455,["हमने ऐसे ऐसे लोग देखे हैं कि जिनकी कुण्डलिनी जब","लोगों ने चढ़ाई, तो यहाँ से लेकर यहाँ तक पूरे","ब्लिस्टर्स आए।"]],[1462,["कुण्डलिनी चढ़ी नहीं थी वह तो सिम्पैथेटिक का","रिएक्शन आ गया था जो कि दोनों साइड में वहाँ से","गुज़र रही है, आप देख लीजिये।"]],[1470,["गणेशजी से आप कुण्डलिनी चढ़ाने से रहे। वो तो","पिछवाड़े बैठे हुए हैं, लेकिन जब परदेस से लोग","अपने देश में आते हैं,"]],[1478,["तो वह अपने बाथरूम से ही या अपने बहते हुए","नाली से अंदर से घुस के आते हैं सब लोग और फिर"]],[1485,["वहीँ का वर्णन अपने देश के बारे में देने","लग जाते हैं - गधे हैं बिलकुल।"]],[1489,["आना है तो महाद्वार से आयें और समझें","कि हमारे देश की सभ्यता क्या है।"]],[1495,["जो भी आता है, ह्यूम जैसा इतना पढ़ा लिखा आदमी,","जिसको मैं बहुत मानती हूँ, वह भी गधा ही था"]],[1501,["क्योंकि वह भी उसी रास्ते से आया और उसने","सारा तांत्रिक इसका महत्व फैलाया।"]],[1508,["इनको इसलिए बताने के लिए हमारे पास कोई भारतीय","नहीं रहेगा क्योंकि भारतीय पढ़ते ही नहीं और"]],[1514,["न ही इस चीज़ को समझने की कोशिश करते हैं कि","कुण्डलिनी का शास्त्र असल में क्या है।"]],[1522,["जिस वक़्त कुण्डलिनी आपकी जागृत होती है,","आपको आश्चर्य होगा, उस वक़्त आप अबोध बालक","जैसे हो जाते हैं"]],[1528,["क्योंकि गणेश पहले ही जागृत हो जाते हैं। पहले तो","गणेश को ही - हाथ से जो वायब्रेशन्स जा रहे हैं,"]],[1535,["आपके हाथ मेरे ओर हैं - जो वायब्रेशन्स आपके हाथ से","गुज़र के जाते हैं, वह पहले गणेश को ही खबर करते हैं"]],[1541,["कि, \"हाँ, अब माँ आ गयी है सामने,\" और आप एक छोटे","बालक जैसे हो जाते हैं क्योंकि वह बीच का रास्ता ही","तोड़ देते हैं।"]],[1554,["उसके बाद ही कुण्डलिनी उठती है - जब तक गणेश","सैंक्शन नहीं करेंगे कभी कुण्डलिनी नहीं उठेगी।"]],[1561,["अगर आप बिलकुल ही अपवित्र आदमी होंगे, तो","कुण्डलिनी उठ नहीं सकती या किसी ने आपके","मूलाधार पे आघात किया होगा तो भी नहीं उठेगी।"]],[1570,["अधिकतर आज कल के गुरु यही धंधा कर रहे हैं।","आपकी कुण्डलिनी को ये लोग तोड़ते हैं।"]],[1576,["मुझसे लोग बहुत नाराज़ होते हैं जब मैं गुरुओं","को बुरा भला कहतीं हूँ। \"माताजी मत कहो।\""]],[1580,["क्या मैं उनके गले में हार पहनाऊँ और उनकी आरती","उतारूँ , जो आपकी कुण्डलिनी को तोड़ते हैं,"]],[1585,["जो आपके पुनर्जन्म होने का सारा ही संसार ही तबाह कर देते","हैं और आपको उससे वंचित कर देते हैं जो आपका अपना अधिकार है?"]],[1599,["इन लोगों को आपके पैसे से मतलब है, वो","आपके पैसे खायें, उससे मुझे हर्ज़ नहीं है।"]],[1604,["चोरी करें, उसमें भी मुझे हर्ज़ नहीं है, जो करना","है करें, डाकू बनें, आपकी औरतों को ख़राब करें -"]],[1609,["अगर आपकी औरतें इतनी बेवक़ूफ़ हैं तो","खराब हो जाएँ, मुझे उससे मतलब नहीं है"]],[1612,["लेकिन कुण्डलिनी पर जब वो हाथ मारते हैं","और कुण्डलिनी को ही खराब करते हैं, तो इनको","राक्षस की ही संज्ञा देनी चाहिए।"]],[1623,["और हैं ये राक्षस। ऐसे सोलह राक्षस कमसकम","मुझे मालूम हैं जो बड़े बड़े राक्षस हैं।"]],[1627,["इनको बहुत बार देवियों ने मारा और बार बार","वह जन्म लेते हैं और उन्होंने फिर से जन्म","इसी कलयुग में लिया है।"]],[1633,["और छह राक्षसनियाँ हैं उन्होंने भी जन्म लिया हुआ है","और लोग उनको पूजते हैं। इत्ते (इतने) बेवक़ूफ़ लोग हैं, उसकी कोई हद्द नहीं।"]],[1646,["ये जो कुण्डलिनी हैं, यह आपकी माँ हैं, ये वहां बैठी","हुईं हैं, इंतज़ार में, कि वह दिन आये कि मेरा बेटा","उसका पुनर्जन्म हो।"]],[1656,["यही आपको पुनर्जन्म देगीं। इसी से आप द्धिज","जाने वाले हो। तब गर आप सुपरफीशयल आदमी हैं,"]],[1663,["आपमें कोई गहराई नहीं, आप चाहते नहीं थे,","कुण्डलिनी खुद ही उठती नहीं है।"]],[1669,["आपने अगर गलतियाँ करीं हैं, तो भी वह","बताती है कि इन्होंने यह गलती की है।"]],[1677,["आपके चक्रों पे पता हो जाता है कि यह आपने गलती","की, वो आपने नहीं की और इसी तरह से कुण्डलिनी का","पूरा पता चल जाता है।"]],[1686,["लेकिन अगर आप अपनी कुण्डलिनी को ठीक से","संभाल के रखे रहें, जैसे कबीर ने कहा कि, \"दास कबीर","जतन से ओढ़ी, जैसी थी तैसी रख दीनी चदरिया,\""]],[1700,["उसी वक़्त, ऐसे सब लोगों की कुण्डलिनी बहुत","आसानी से जागृत हो जाती है।"]],[1707,["अब इसके बाद जो ऊपर का चक्र है, जिसे स्वाधिष्ठान","चक्र कहते हैं, यह हमारे नाभी से निकलता है"]],[1713,["और चारों तरफ घूमता है। इसे स्वाधिष्ठान चक्र कहते","हैं और यह नाभी से निकल के चारों तरफ घूमता है।"]],[1720,["स्वाधिष्ठान चक्र से हमारा चित्त कार्यान्वित होता है,","अटेंशन। जहाँ हम अटेंशन डालते हैं वहाँ स्वाधिष्ठान","कार्य करता है।"]],[1732,["इसीलिए जब हम बहुत ज़्यादा विचार करने लगते हैं,","तब भी स्वाधिष्ठान चक्र पेट का जो मेद होता है,"]],[1739,["जो फैट होता है, उसको परिवर्तित कर देता है, उसको","ट्रांसफॉर्म कर देता है कि वो जाके हमारे बुद्धि में","उपयोग में लाये।"]],[1751,["बुद्धि में भी तो मेद होता है, फैट ग्लोब्युल्स होते हैं।","ये जो फैट ग्लोब्युल्स हैं, जिसको हम इस्तेमाल","करते रहते हैं,"]],[1758,["उसके लिए अपने पेट से ही स्वाधिष्ठान चक्र","बना कर के फैट ग्लोब्युल्स ब्रेन में देता है।"]],[1766,["यही चक्र है जिसके कारण, हमारा लिवर - ऊपर का","हिस्सा, हमारा स्प्लीन, और हमारा पैंक्रियास, किडनी","और यूटरस का कुछ हिस्सा चलता है।"]],[1779,["ये क्रिएशन का चक्र है। जब हम जितना सोचते","हैं आगे के लिए, हम क्रिएट करना चाहते हैं,"]],[1785,["जितना हम फ्यूचर के बारे में सोचते हैं और","प्लैनिंग करते हैं, उतना ही यह चक्र चलता है।"]],[1792,["अब ये हमारे अटेंशन को प्लावित करता है,","हमारे चित्त को प्लावित करता है।"]],[1800,["जिस आदमी का लिवर खराब है, उसका चित्त","हमेशा दुखी रहेगा, एक अनमना सा रहेगा।"]],[1806,["उसको कुछ चीज़ अच्छी नहीं लगेगी। उसका दोष","नहीं, क्योंकि उसको लिवर उसका ठीक नहीं है।"]],[1813,["इसीलिए उसको लिवर कहते हैं - कि आप","लाइफ जीवन से सम्बंधित है।"]],[1819,["उसी प्रकार, जो आदमी बहुत ज़्यादा सोचता है,","और बहुत ज़्यादा प्लैनिंग करता है, उसका भी","स्वाधिष्ठान चक्र खराब हो जाता है,"]],[1826,["क्योंकि, या तो वह सोचने का काम करे और वहाँ","पर अपना वो ब्रेन जो है, ब्रेन के लिए सप्लाई"]],[1832,["करता रहे बेचारा और या तो इन सब ऑर्गन्स को देखे।","उसमे से जो पैंक्रियास हैं, ये जब खराब हो जाता है, तो","आपको डायबिटीज की बीमारी हो जाती है।"]],[1842,["डायबिटीज की बीमारी सहज योग में सौ","फ़ीसदी ठीक होती है, सौ फ़ीसदी।"]],[1848,["इस तरह की अति विचारणा से मनुष्य की","राइट साइड बहुत ज़्यादा काम करती है"]],[1855,["और जो लेफ्ट साइड है वो एकदम निराश्रित हो जाती","है या कहें निराश हो जाती है, निग्लेक्टेड हो जाती है।"]],[1865,["इसी के कारण, जब मनुष्य बहुत ज़्यादा","सोचता है, बहुत मेहनत करता है,"]],[1872,["फ़िज़िकल एफर्ट, जिसको कहना चाहिए, शारीरिक,","तो उसको हार्ट अटैक आ जाता है।"]],[1878,["जब उसको हार्ट अटैक आ जाता है, तो उसको समझ","लेना चाहिए कि अब मैंने अति कर दी, इम्बैलेंस,","असंतुलन उसके अंदर आ गया।"]],[1888,["उसको अब फ़ौरन समझ लेना चाहिए कि अब उसको","थोड़ा सा अपने इमोशंस की तरफ भी ध्यान देना","चाहिए और बैलेंस में आना चाहिए।"]],[1894,["सहज योग में पार होने के बाद बैलेंस लाने की बहुत","ही सादी क्रिया है कि आप लेफ्ट साइड तो उठा के","राइट साइड में कर दीजिये।"]],[1904,["अभी भी बहुत से लोग विचारक यहाँ पे आये थे","जिनको पार नहीं हो रहे थे, उनकी लेफ्ट साइड उठा के"]],[1909,["राइट साइड को कर दी, तीन बार भी कर दी,","तो भी कुण्डलिनी बाहर निकल गयी।"]],[1913,["क्योंकि जैसे आपने ऊपर देखा है, कि जब आप बहुत","विचार करते हैं या बहुत कुछ कार्य में संलग्न होते हैं,"]],[1921,["तो आपका ईगो अहंकार डेवलॅप होता है, जो कि","ऊपर दिखाया गया है, जो असल में सर में से,"]],[1929,["इस तरह से घूमता हुआ यहाँ तक एक बलून के जैसे","पलता जा रहा है। और जब आप अपने अंदर","कंडीशनिंग करते हैं,"]],[1937,["मतलब उस ईगो को दबाने की कोशिश करते हैं,","तो आपके अंदर प्रतिअहंकार जागृत होता है,","जिसे सुपरईगो कहते हैं,"]],[1944,["वो आपके पीछे से ले करके राइट साइड","में यहाँ तक आता है - वो भी असंतुलन है।"]],[1949,["इस तरह के दो बलून आपके अंदर तैयार हो जाते हैं।","जब एक बलून दूसरे से ज़्यादा डेवलॅप हो जाता है,"]],[1960,["तो वो दूसरे पे काबू पा लेता है और उसको दबा देता है।","आजकल हिंदुस्तानी लोगों का ईगो ज़्यादा बढ़ा हुआ है"]],[1967,["क्योंकि हम लोग डेवलॅप कर रहे हैं, तो बहुत प्लैनिंग","कर रहे हैं, बहुत कार्यरत हैं - बहुत सोचने से हमारा","ईगो बढ़ा हुआ है।"]],[1975,["आजकल पाश्चिमात्य लोगों का सुपर ईगो बढ़ गया","क्योंकि उनका इतना ईगो बढ़ गया था पहले, इतना","ईगो बढ़ गया, कि सुपर ईगो को एकदम दबोच मारा।"]],[1985,["तो परेशान हो गए लोग बिलकुल। तो उन्होंने","सोचा इसकी कोई न कोई पकड़ लेनी चाहिए।"]],[1991,["तो उन्होंने अवलम्बन किया ड्रग्स वगैरह का।","ड्रग्स वगैरह के अवलोकन से सुपर ईगो बढ़ गया।"]],[1997,["सुपर ईगो ने इतना धक्का दिया कि ईगो इधर आ गया","और सुपर ईगो बढ़ गया। अब इन दोनों के बीच में","वोब्ब्लिंग हो रहा है।"]],[2005,["इधर से उधर धक्का मार रहे हैं और कहीं वो ठिकाने से","नहीं हैं। पूरी समय उनके अंदर वोब्ब्लिंग में दिमाग है।"]],[2011,["अजीब परेशान लोग हैं। आप जानते हैं कि लोग","सबसे ज़्यादा जो सुबत्ता वाले देश हैं, स्वीडन जैसे देश","में सबसे ज़्यादा आत्महत्याएँ हो रहीं हैं"]],[2020,["क्योंकि ये दिमाग में ईगो, सुपर ईगो का झगड़ा चालू","है। उनके बस का नहीं जीना। एक मिनट में आपको,"]],[2027,["आप अगर देखें, तो सब मिल बैठे हैं वहाँ अमेरिकन,","तो उनकी किसी की नाक सुकड़ रही है, किसी का","सर चल रहा है,"]],[2033,["किसी की आँख फड़क रही है, किसी का मुँह ऐसा-ऐसा","हो रहा है - एक मिनट भी वो शान्ति से नहीं बैठ सकते।"]],[2039,["सारे आँख यहाँ पर बल पड़े होंगे बड़े-बड़े।","जवान लोगों के आप देखिएगा तो बड़े बड़े बल","पड़े होएँगे - यहाँ पर चिंता।"]],[2049,["इसकी वजह ये है के उनके अंदर ईगो और सुपरईगो","का झगड़ा खूब चल पड़ा है और इतना ज़्यादा"]],[2057,["भ्रम और कन्फ्यूजन उनके माइंड में है, कि वो","समझ ही नहीं पाते कि क्या चीज़ है।"]],[2061,["और इसी का फ़ायदा उठा कर के, जितनी भी","आसुरी शक्तियाँ हैं या नेगटिविटीज़ हैं, वो सारी","उनकी खोपड़ी में घुस जातीं हैं।"]],[2069,["और इसीलिए वो ऐसी-ऐसी चीज़ों का अवलम्बन करते","हैं, जिससे वो पलायन कर सकें और इस संसार के जो","कुछ भी प्रश्न हैं उससे दूर भागें।"]],[2084,["ये स्वाधिष्ठान चक्र बहुत ही महत्वपूर्ण है क्योंकि जो","लोग अति कार्य करते हैं, जब वह अतिशयता पे पहुँच","जाते हैं तो -"]],[2093,["इसे हम सुपरा कॉन्ससियस एरिया कहते हैं","क्योंकि राइट हैंड साइड पर है -"]],[2098,["वो जब अति क्रमण कर जाते हैं, तो वो","कलेक्टिव सुपरा कॉन्ससियस में चले जाते हैं।"]],[2103,["इस प्रकार जब वह लेफ्ट साइड पे अतिक्रमण","करते हैं, तो वह सब कॉन्ससियस से कलेक्टिव","सब कॉन्ससियस में चले जाते हैं।"]],[2112,["मनुष्य के ऊपर का जो हिस्सा है वह कलेक्टिव","कॉन्ससियस है। अब जो लोग बहुत ज़्यादा मरे हुए","आदमियों पे विचार करना,"]],[2126,["मृत्यु पर विचार करना, विशेषकर बुद्ध धर्मी","लोगों में बहुत ज़्यादा यह चीज़ आ गई;","आश्चर्य की बात है"]],[2133,["कि बुद्ध धर्मियों ने पता नहीं क्यों मृत्यु को इतना","ज़्यादा माना हालाँकि, मेरे विचार से, बुद्ध ने","कभी नहीं माना होगा।"]],[2142,["और बुद्ध ने तो यहाँ तक कहा था किसी भी चीज़","की, मरी हुई चीज़ की आप पूजा न करें।"]],[2148,["उसके उलटे बिलकुल ही, बुद्धिस्ट जो लोग हैं, बहुत से","बुद्धिस्ट, लद्दाख में जाइये तो, तिब्बत में जाइये तो,"]],[2154,["सारे ही प्रेत विद्या है। प्रेत विद्या, शमशान विद्या,","भूत विद्या - महावीर के भी लोगों का यही है।"]],[2162,["लेकिन महावीर से भी ज़्यादा इन लोगों ने","अतिशय कर दिया। कमस कम महावीर के लोग"]],[2167,["उसके उलटे चलने की वजह से, या चाहे जैसा भी हो,","वो मंदिर बनायेंगे, पहले गुफाएं बनायेंगे,","कहीं चित्रकारी करेंगे,"]],[2175,["कहीं कुछ नहीं मिला तो कपड़ों की दुकाने बनायेंगे,","कपडे बेचेंगे, इस तरह के कार्य करते हैं।"]],[2181,["और बुद्ध के लोग, जिसने कि कभी भी मृत्यु की कभी","बात नहीं की थी - महावीर ने ज़रूर मृत्यु और नर्क की","बात की थी -"]],[2189,["लेकिन बुद्ध ने कभी मृत्यु की बात नहीं की","- सब के सब मृत्यु पे लगे हुए हैं।"]],[2197,["लद्दाख में तो साइन बनाया हुआ है कि किस आदमी को","किस तरह बिठाना चाहिए, उसको कैसे गाड़ना चाहिए,"]],[2203,["उसका हाथ कैसे काटना चाहिए, उसको कहाँ उसका","हाथ रखना चाहिए, उसकी कैसी व्यवस्था करनी चाहिए -"]],[2208,["कौन से बुद्ध की किताब में लिखा, मैं तो जानती नहीं हूँ","लेकिन वो कभी भी ऐसी बात लिख नहीं सकते, यह मैं","अभी बात बता रही हूँ।"]],[2216,["सारी प्रेत विद्या, भूत विद्या, पिशाच विद्या, सारी","हमारे (बिलकुल) लेफ्ट साइड में घुसे चली जाती है"]],[2223,["और इसके साथ आपके पास में सूत्र हैं जिनके आपने","नाम भी सुने होंगे के, जिसे हम कहते हैं हाकिनी,","डाकिनी, शाकिनी, वगैरह, वगैरह।"]],[2234,["इस तरह के सात तार हैं, जिसके झंकार होते हुए,","रेजोनेंस के साथ में आदमी ढकेलता हुआ चला जाता है","कलेक्टिव सब कॉन्ससियस में।"]],[2242,["और कलेक्टिव सबकॉन्ससियस में, सामूहिक सुप्त","चेतन में, जितने भी मरे हुए लोग हैं सारे,"]],[2248,["ये मरे हुए लोग वो होते हैं, जो ज़िन्दगी से घबड़ाये","हुए, भागे हुए, पलायत, जो बहुत ही दुष्ट प्रवृत्ति","के भी होते हैं,"]],[2259,["महादुष्ट प्रवृत्ति के भी हो सकते हैं लेकिन उनमें","हिम्मत नहीं कि खुले आम यह काम करें, वह बहुत","सीक्रेटली यह गंदे काम करते हैं।"]],[2268,["यह लोग जो इस प्रकार के अतृप्त होते हैं,","वह भी वहीँ पर विचरण करते हैं।"]],[2277,["उससे परे ही हमारा स्थान होता है जब हम मर जाते","हैं, तो हम कलेक्टिव सबकॉन्ससियस में रहते हैं"]],[2283,["लेकिन हम उस दिन का इंतज़ार करते रहते हैं","जिस दिन हमारा पुनर्जन्म होगा।"]],[2288,["हम उस चीज़ को नहीं मानते हैं कि आप","अतृप्त भावना से यहाँ भटकते हैं।"]],[2293,["ये भटकते हुए जीव जो होते हैं, लेफ्ट साइड में,","वो बहुत ही ख़राब होते हैं, और जब वो अपने शरीर में"]],[2300,["या अपने आज्ञा चक्र से जब प्रवेश करते हैं,","तो मनुष्य को जो मिर्गी जैसी बीमारियाँ,"]],[2306,["या सर फिर जाना, या जिसे कहते हैं कि पागल हो","जाना, दुनिया भर की इस तरह की बीमारियाँ हो","जातीं हैं।"]],[2317,["यह सारी इड़ा नाड़ी की बीमारियाँ हैं और जो","साइकोलॉजिस्ट जिसे ट्रीटमेंट देते हैं वो सारी बीमारियाँ","हमें लेफ्ट सबकॉन्ससियस से होतीं हैं।"]],[2327,["अब हमारे जो फ्रायड साहब थे वो भी एक ही अक्लमंद","थे। उनको तो मेरे ख्याल से उनको एक आँख से","दिखता था, दूसरी आँख ठीक नहीं थी।"]],[2335,["वो सिर्फ यही साइड देखते थे, उन्होंने दूसरी साइड देखी","ही नहीं। वो कहते थे कि सारा कंडीशनिंग है बाकी","कुछ नहीं।"]],[2342,["और उसकी शुरुआत क्योंकि सेक्स से होती है,","उन्होंने सारी चीज़ लाकर के उसके सामने रख दी।"]],[2349,["काश वह थोड़ा सा भारतीय काम शास्त्र पढ़ते","तो उनकी अक्ल थोड़ी सी ठीक होती।"]],[2357,["लेकिन इतनी एकांगी उनकी दृष्टि थी, वह एक ही","साइड में देखते थे और स्वयं जीवन में वह अत्यंत","घृणित आदमी थे।"]],[2363,["उनका अपने माँ से ही गन्दा सम्बन्ध था इसलिए","उन्होंने सारी चीज़ ला कर के रख दी है।"]],[2368,["और होता भी है। अगर साइकोलॉजिस्ट हर समय","पागल आदमियों के साथ रहेगा, तो ख़ुद ही  पागल","हो जायेगा।"]],[2374,["उसके अंदर वह सारी गंदगियाँ आ जातीं हैं","जो वह पागल आदमियों से देखता है।"]],[2379,["यह शायद साइकोलॉजिस्ट जानते नहीं। अब हमारे","यहाँ आये हुए है एक, जो वहाँ के बड़े अच्छे","साइकोलॉजिस्ट हैं, वो ख़ुद बताते हैं।"]],[2386,["क्योंकि अगर किसी आदमी को टी.बी. हो जाए,","तो हम समझते हैं कि उसे टी.बी, हो गया हमें","बचाव करना चाहिए"]],[2391,["लेकिन इन भूत प्रेत से बचाव करने का","हम कोई तरीका नहीं जानते हैं।"]],[2395,["हम लोग जब उनसे डील करते हैं, उनसे जब बातचीत","करते हैं, तो हो सकता है कि वो भी हमें कुछ दे दें।"]],[2402,["और इसी कारण बहुत से लोगों की बीमारियाँ लोग","ठीक नहीं कर सकते क्योंकि वो इसे देख नहीं पाते,"]],[2408,["यह सूक्ष्म चीज़ें हैं, यह अपने अंदर वास करती हैं,","लेकिन ये ज़रूर होतीं हैं, और यह स्थित होती हैं।"]],[2415,["अब राइट साइड में जो आप जाइये तो इससे राइट","में आपको सुपरा कॉन्ससियस एरिया में"]],[2421,["आप अगर पहुँचें, तो वहाँ से आप अगर अति क्रमण","कर दें, तो आप कलेक्टिव सुपरा कॉन्ससियस में","चले जाते हैं।"]],[2428,["इस जगह ऐसे लोग रहते हैं, जो बहुत महत्वाकांक्षी","होते हैं, एम्बिशयस लोग होते हैं, जो हमेशा फ्यूचर","की बात करते हैं।"]],[2443,["जो लोग फ्यूचर की बात; आत्मा जब किसी की तृप्त हो","जाए, तो वह तो फ्यूचर की जगह पहुँच जाते हैं"]],[2450,["लेकिन जैसे हिटलर मारा होगा तो वह यहीं बैठा","होएगा क्योंकि अभी अतृप्त है, तो वह वहाँ नहीं होगा।"]],[2457,["बहुत ज़्यादा जो महत्वाकांक्षी लोग होते हैं,","उनके लिए यह जगह बनी हुई है।"]],[2461,["जब आप सुपरा कॉन्ससियस में चले जाते हैं तो","आपके अंदर इसी में से प्रेत आते हैं।"]],[2467,["जब ये स्पिरिट्स आपके अंदर आ जायेंगे,","तो वह आपके अंदर चालना भी करेंगे।"]],[2471,["आप वही चीज़ करेंगे पागल जैसे काम करेंगे","(अस्पष्ट)।"]],[2477,["पागल जैसे वह दौड़ता रहेगा। अभी आप देखिएगा","उसको हार्ट अटैक आएगा या फिर पागल हो जाएगा,","फिर लिप्त हो जाएगा।"]],[2484,["बहुत से बच्चे आपने देखा होएगा पढ़ते होएँगे","उसके बाद में फर्स्ट क्लास फर्स्ट और देखा हटात,"]],[2492,["फर्स्ट क्लास फर्स्ट आने के बाद एकदम (अस्पष्ट)।","यह बड़ी कॉमन सी बात है। ये इसी वजह से है।"]],[2499,["किसी भी चीज़ की इतनी महत्वाकांक्षा करने की,","यह अतिशय पे चलने के लिए .....।"]],[2508,["अगर वो बहुत ज़्यादा (अस्पष्ट)","ये नहीं होना चाहिए (अस्पष्ट)"]],[2512,["हठ योग या ट्रान्सेंडैंटल मैडिटेशन यह भी यही है।","इसमें सिर्फ आपके अंदर इस तरह का महत्वाकांक्षी","भूत भर दिया जाता है।"]],[2520,["राम नाम का एक ऐसा भूत आपके अंदर भर दिया","आप लगे काम में। खूब आपने मेहनत करना शुरू","कर दी।"]],[2526,["दस साल के अंदर आपकी यह हालत होती है जैसे","कि टूटी हुई मोटर खड़ खड़ खड़ खड़ कर चले।"]],[2532,["अभी मैं (अस्पष्ट - मिलान?) में गयी थी सबसे पहले","वहीँ पर ट्रान्सेंडैंटल मैडिटेशन ... वहाँ जितनों ने किया"]],[2536,["आज आप जा कर के देख लीजिये आप कान","पकड़िएगा कभी इन्वॉल्व (अस्पष्ट - नहीं होएँगे?)।"]],[2543,["क्योंकि जब आप ट्रांस में जाते हैं तो आप इसी","सुपरा कॉन्ससियस एरिया में (जाते हैं)"]],[2547,["और ये सुपरा कॉन्ससियस के भूत सबके और","आप पे ये भूत सवार हो जाते हैं।"]],[2551,["ट्रांस का भूत आपके पे सवार हो जाता है।","आपका जो अपना है वो तो सब खो जाता है"]],[2556,["आप दूसरे का ही बोझा अपने सर पे ले कर घूमते हैं।","समझ लीजिये आपके ऊपर हिटलर आ के बैठ गया।","आपकी क्या दशा हो जाएगी?"]],[2562,["हो सकता है आप बड़े सक्सेसफुल आदमी हो जाएँ,","बड़े यशस्वी दुनिया को नज़र आयें, लेकिन दस","साल बाद आपकी जो हालत हो जाएगी -"]],[2569,["दस भी नहीं मुश्किल से आपके एक ही साल में","(अस्पष्ट) इसलिए अगर कोई बड़ा भारी बुद्धिस्ट बैठा","होता है, तो वो एक ही साल में नज़र आ जाता है।"]],[2576,["आपके दिल्ली में एक साहब थे। पिछले साल जब हम","आये थे तो वो हमारे सामने आ के कहने लग गए,"]],[2582,["\"माँ मेरा तो ये हाल हो गया है कि मेरी हिम्मत","ही नहीं चलते मैं थर थर काँपता हूँ। कहीं सुगंध आती","तो मेरी सांस फूलने लग जाती।"]],[2588,["मेरा ये हाल हो गया है कि मैं कहीं मंदिर","मस्जिद के सामने से गुज़र नहीं सकता।"]],[2592,["कोई भगवन का नाम लेता तो मेरा जी धकधकाने","लगता। ये है क्या ?\" इनका निकला भूत मैंने।"]],[2599,["तब वो ठिकाने से रहीं। तो ये ही चीज़ भूत है,","और इसीलिए आपको समझ लेना चाहिए","ये दोनों ही चीज़ गलत हैं।"]],[2610,["बीचों-बीच रहना चाहिए। मध्य का मार्ग, यही","बात बुद्ध ने भी कही। यही बात सबने कही है","कि मध्य में रहना चाहिए।"]],[2619,["अब मध्य में नाभि चक्र जो बीचों बीच है उसके","बारे में कल मैंने आपको किसी और का बताया था"]],[2623,["कि हमारे देश का नाभि चक्र खराब हो गया है।","एक तो हमें परमात्मा (अस्पष्ट) इसका ही"]],[2631,["आपको परमात्मा क्यों सुख दे, क्यों शांति","दे, क्यों आनंद दे, क्यों आरोग्य दे,"]],[2637,["आपको उसकी ज्योत तक नहीं,","आप उसको जानना भी नहीं चाहते,"]],[2641,["आप इधर भटक रहे हैं, उधर भटक रहे हैं,","दुनिया भर की धूल छान रहे हैं।"]],[2645,["हम परमात्मा की ओर से आपसे पूछते हैं? आपने","कौन सा परमात्मा के साथ न्याय किया हुआ है?"]],[2651,["उसने सारी सृष्टि आपके लिए बनाई, आप अपने सिर","फुटौअल कर रहें हैं। आपस में लड़ाई झगड़ा कर रहें हैं।"]],[2657,["दो भाई भी प्रेम से नहीं रह सकते - तो क्यों","परमात्मा आपके लिए कुछ करे ?"]],[2661,["जो कुछ भी प्रश्न आपने आज खड़े किये हुए हैं","संसार में, सारे मनुष्य के प्रश्न खड़े किये हुए हैं।"]],[2666,["ये मनुष्य ने ही तानाशाही अपना ली है और परमात्मा","को भूल कर के और (अस्पष्ट) कर रहा, फिर क्यों","परमात्मा उनकी मदद करे?"]],[2673,["उसके लिए क्या है? आज आपको पैदा किया, कल","आपको सबको नष्ट कर के दूसरी दुनिया बनाएगा।"]],[2678,["उसको आपसे कोई मतलब नहीं। ये तो मैं ही एक माँ हूँ","जो चाहती है कि ले (अस्पष्ट) और होने ही वाला है।"]],[2686,["आप क्या सोचते हैं? आप आराम से बैठे","रहिए, वो चीज़ होने वाली है।"]],[2690,["यह तो ठीक है अभी टाइम दिया हुआ है, आप लोग","पार हो लीजिए तो ठीक है और नहीं तो कल्कि का","अवतरण आने वाला है।"]],[2697,["और जब वो आएगा, वो किसी को देखने नहीं वाला,","वो कोई किसी को रिऐलिज़ेशन देने वाला नहीं,"]],[2702,["लेक्चर देने वाला नहीं, मेरे जैसे आप लोगों से","झिक झिक करने वाला नहीं कि, \"बाबा, जमो, जमो,जमो।\""]],[2706,["वो तो एक तलवार ले कर के धड़ा धड़ सबको","आखिर काट कर के ठिकाने करने वाला"]],[2711,["और ऐसी सिचुएशन करेगा कि आपको","पता नहीं चलेगा कि आप कहाँ हैं।"]],[2716,["इसलिए समझ लेना चाहिए कि ये आखिरी वक़्त  हमें भी मिला है और आखिरी वक़्त भी आ गया है","और हम इसे पा लें।"]],[2726,["गलत रस्ते पे चल कर के, गलत चीज़ों में","उलझ करके अपने जीवन को बर्बाद न करें।"]],[2731,["क्योंकि आपका जीवन बहुत ही महत्वपूर्ण है।","कितनी मुश्किल से बनाया, देखिये आपके अंदर","ये सारे चक्र परमात्मा ने बनाये हैं।"]],[2738,["पहले तो मूलाधार चक्र जैसा सुन्दर चक्र जिस पर","श्री गणेश बसे हैं, फिर कुण्डलिनी की व्यवस्था जिसे","आपक मुलाधार कहते हैं,"]],[2744,["उसके बाद स्वाधिष्ठान चक्र, जिस चक्र के कारण आप","सारे, सारे सृष्टि को आप कण्ट्रोल कर सकते हैं।"]],[2752,["देखिये हम आ रहे थे यहाँ पर, हमें लोगों ने बताया कि","दिल्ली में तो ख़ूब बारिश हो रही हमने कहा,","\"चिंता नहीं करो हमें पहुँचने तो दो।\""]],[2758,["जिस दिन से हम पहुँचे बारिश बंद। एकदम","बारिश बंद हो गई। कोई मुश्किल काम नहीं।"]],[2766,["हम तो कहते हैं कि सूरज-वूरज को भी करना","कोई मुश्किल नहीं - इंसान को ठीक करना","बड़ा ही कठिन है।"]],[2772,["सबसे मुश्किल चीज़ तो इंसान है। सूरज और चाँद","और सितारे सब परमात्मा के इशारे पर चलते हैं।"]],[2780,["कोई कठिन काम नहीं है पर मनुष्य जो स्वतंत्र  है, उसके सामने","तो परमेश्वर भी नत मस्तक हैं।"]],[2786,["वो क्या करें, वह किस तरह से समझायें, कि \"देखो,","तुम्हारे अंदर कितनी सुन्दर चीज़ बनाई हुई है,"]],[2791,["इस सुन्दर चीज़ से परमात्मा को पा लो, इससे आनंद","उठा लो।\" लेकिन मनुष्य को दो मिनिट की","चैन नहीं है,"]],[2797,["कि वो ज़रा बैठे, परमात्मा में जमे, उसमें","सजग हो, उसे पाएँ और दूसरों को भी दें।"]],[2803,["उसके पास टाइम ही नहीं है, हालाँकि हर समय","घड़ी बाँधे रहता है। किस चीज़ के लिए परमात्मा","ने आपको टाइम दिया हुआ है?"]],[2809,["किस चीज़ के लिए? परमात्मा ने ये सारी सृष्टि","की सारी चीज़ें, असल में, जिसको कहते हैं आप","साइंस वगैरह,"]],[2815,["ये सब काहे के लिए खोल कर के आपको बताया हुआ","है। यह सारी शक्तियाँ आपको कहाँ से मिलीं?"]],[2819,["किस चीज़ से टाइम बचाना है। सब टाइम बचाएँगे।","हमें टाइम बचाना है टाइम बचाना है - काहे के लिए?"]],[2825,["कहने लगे, \"वो हमें पब में जाना है, इसलिए हम टाइम","बचा रहे।\" क्या कहने! टाइम बचा कर के और हमें","बॉलरूम में डांस करने जाने का है।"]],[2834,["ये टाइम बचाना। टाइम इसलिए बचाना है कि आप","ध्यान करें, ध्यान में जमें और पाएँ, इसीलिए परमात्मा","ने ये सारी शक्तियाँ आपको दीं हैं।"]],[2844,["अब इसी के ऊपर आप देखें कि मैंने आपको नाभि चक्र के बारे","में कल कहा था कि नाभि चक्र कितना महत्वपूर्ण है।"]],[2851,["इसलिए ज़्यादा नहीं बताऊँगी लेकिन","नाभि चक्र से ही मनुष्य उठता है।"]],[2855,["जब वह परमात्मा को पा लेता है तभी उसकी","दृष्टि परमात्मा की ओर उठती है, तभी वो ख़ुद भी पार होता है, तभी उसकी","दृष्टि ऊपर जाती है।"]],[2862,["उसकी जब तक खोज सत्ता, पैसा, राजकारण और","दुनिया भर की बिलकुल ही निम्न स्तर की चीज़ों पे","रहती है तब तक उसकी कुण्डलिनी उठने वाली नहीं है।"]],[2872,["अब ये जो चक्र है ये बहुत ही महत्वपूर्ण हमारे","अंदर स्थित है और इसको संजोना चाहिए"]],[2878,["और समझना चाहिए अपने नाभि चक्र को किस","तरह से ठीक रखना चाहिए क्या करना चाहिए"]],[2884,["उसके बारे में भी आप इन लोगों से बातचीत","करियेगा, ये बताएँगे आपको।"]],[2888,["उसके ऊपर में जो चक्र है, क्योंकि बहुत ही आवश्यक","चक्र है, विशेष रूप से हमारे अंदर बनाया गया है।"]],[2896,["जब कि नाभि चक्र में हमारे अंदर उत्थान की भूमिका","बनाई गई, इसका मतलब उतक्रान्ति की भूमिका बनाई","गई तब आप जानते कि दशावतरण हुआ।"]],[2907,["याने एक के बाद एक अवतार होते गए। पहले तो","जैसे कि आप जानते हैं मत्स्य का अवतार हुआ","माने, मछली पहले बहार आई।"]],[2914,["मछली के बाद में, जब वो ज़मीन को छू गई, तो","रेप्टाइल्स हो गए, तो कछुए का अवतार हुआ।"]],[2921,["ये सारी चीज़ें शास्त्र में भी हैं और आपने इसमें भी","देखीं हैं। इसी प्रकार एक एक एक एक जीवन आते गए।"]],[2928,["अवतार का मतलब ये नहीं कि वो गुज़र गए।","वो आता है और आपको ऊपर बिठाता है लेकिन ये जो"]],[2933,["पहले परमात्मा के अंश स्वरुप से उठता है,","और आपको बताता है, आपको गाइड करता है,","और आपके अंदर उनका स्थान बन जाता है।"]],[2940,["तो इसी से, जितने भी अवतार हुए हैं, उसमें से","अधिकतर अवतार भवसागर में ही रहे और वहाँ से","आपकी मदद करते रहे।"]],[2950,["जिस वक़्त से भक्त लोगों ने परमात्मा को पाने का","प्रयत्न किया था तब तब उसपे सैटेनिक या आसुरी","लोगों ने उसे असफल किया।"]],[2960,["उस वक़्त आपको मालूम है कि देवी ने, परमात्मा की","शक्ति ने, स्वयं अवतरण लिया। ऐसे १००० अवतरण","बताये जाते हैं कलयुग में अनेक अवतरण हुए हैं।"]],[2970,["और उन्होंने भवसागर में जो लोग पार होने के हेतु से","यज्ञ आदि करते थे उनकी रक्षा करने का बहुत बड़ा","काम किया और उनकी रक्षा की।"]],[2981,["यज्ञ भी इसलिए किये जाते थे कि, जिससे सृष्टि के","जो पाँच तत्व हैं, उन पाँच तत्वों को जागृत किया जाए।"]],[2989,["इसलिए यज्ञ किये जाते थे। आज उन तत्वों को","जागृत करने की ज़रुरत नहीं, वह सब जागृत","हो गयें हैं आपके अंदर"]],[2995,["इसीलिए आपको इलेक्ट्रिसिटी मिलती है और","आपको मैग्नेटिस्म आप इस्तेमाल करते हैं"]],[3000,["यह सब जागृत होने की ही वजह से आप खेती भी","करते हैं और इसी वजह से आपके सारे जो","कुछ आज हैं"]],[3005,["मास मैन्युफैक्चरिंग जैसे मटेरियल वह इसी वजह","से खुला है क्योंकि यह पाँचों तत्व आपके जागृत हुए हैं","(जैसे आगे का)।"]],[3013,["आज ज़रुरत है कि आपके जो धर्म हैं उसके आपको परे","उठना है। उत्क्रांति की जो चरम सीमा है उसे पाना है।"]],[3024,["यानि आपको आपकी आत्मा से पहचान करवाना","- यही आपका काम है। बाकी सब कार्य हो चुका है","सिर्फ यही अंतिम कार्य आपको है।"]],[3033,["अब यह देवी के लिए मैंने आपको बताया है कि आपकी","रक्षा (अस्पष्ट) के और उनके हज़ार नाम हैं और उनके","बारे में जितना भी कहा जाए उतना कम है।"]],[3043,["आप तो सब जानते ही हैं कि देवी शक्ति कितनी","महत्वपूर्ण है। उनकी कीर्ति डायनामिक है या यह","कितनी सूक्ष्म हैं इसका बताना कुछ आसान नहीं है।"]],[3055,["क्योंकि वो सब देखते हैं जो आपके अंदर हैं नहीं","और उसको समझाना मुश्किल है। यानि कितनी","कार्यान्वित हैं, कितनी सूक्ष्म हैं।"]],[3064,["कितनी ये प्रेममय कि एक जैसे ऊँगली मात्र घूम जाए","और सारी सृष्टि को घुमा दें इतनी इसमें शक्ति है।"]],[3076,["इसीलिए अनेक बार आपके लिए अवतरण लिया","और अनेक राक्षसों का नाश किया जिससे कि आप","फ्री घूम सकते हैं।"]],[3084,["अब इसके ही जो राइट साइड में जो ह्रदय चक्र है,","जिसमे कि बीच में जगदम्बा का स्थान है,","जो कि आपकी माँ हैं।"]],[3093,["जब आप ये भूल जाते हैं कि जगदम्बा आपकी माँ हैं,","तब आपके अंदर अरक्षा का भाव, जिसको कि सेंस","ऑफ़ इन्सेक्युरिटी कहते हैं।"]],[3102,["जब यह हो जाता है तो आपको श्वास की बीमारी हो","जाती है - श्वास की बीमारी जिसको कहते हैं कि","अस्थमा वगैरह उससे।"]],[3112,["अस्थमा और दूसरे जो भी औरतों को जो होता है","ब्रैस्ट कैंसर वगैरह, वो भी इसी सेंटर के (अस्पष्ट)","[ की वजह से] होता है।"]],[3120,["यह सेंस ऑफ़ इन्सेक्युरिटी जगदम्बा का स्थान लुप्त","रहने से होता है और जगदम्बा का स्थान जागृत करने","से ही सिर्फ ठीक होता है।"]],[3129,["जितनी भी इंसान के कैंसर वगैरह बीमारियाँ हैं","सब इस स्थान को जागृत करने से ठीक होती  हैं।"]],[3136,["लेकिन जब तक आदमी यह नहीं जानता कि","हमारे अन्दर जगदम्बा का स्थान है, मतलब","जानना मतलब प्रभुत्व -"]],[3144,["मेरा मतलब जानने से ज्ञान नहीं - ज्ञान और बोध में","बहुत अंतर है - बोध होना, जब उसे ये बोध हो जाता है"]],[3151,["कि जगदम्बा हमारे अन्दर स्थित है, तभी","उसका यह स्थान ठीक होता है।"]],[3156,["इसके राइट साइड में जो चक्र दिखाई दे रहा है, वो","श्री राम का स्थान है। यहाँ श्री राम का अवतरण है।","ये पिता का स्थान है।"]],[3167,["लेफ्ट साइड में जगदम्बा का स्थान है,","बीचों बीच जगदम्बा का, और लेफ्ट में पार्वतीजी","का, जो कि हमारी माँ हैं।"]],[3176,["वह माँ का स्थान है, वो जो लेफ्ट में है। आपके","अगर लेफ्ट चक्र में पकड़ा हो तो आपके माँ के","बारे में अगर पूछा जाये,"]],[3184,["तो पता होगा कि या तो माँ बीमार हैं,","या मर गईं हैं, या मरने को हैं।"]],[3188,["अगर लेफ्ट की बिलकुल यह स्टिल हो जाता है","तो आपको ह्रदय की बीमारी होने वाली है।"]],[3193,["लेफ्ट की थोड़ी अगर पकड़ आ जाए, तो मैं","देखती हूँ कि आपको ह्रदय की बीमारी है।"]],[3200,["उसके बाद जो ऊपर का चक्र है यहाँ (अस्पष्ट) बहुत","ही महत्वपूर्ण है। उसका नाम विशुद्धि चक्र है।"]],[3206,["और इसमें से सोलह हज़ार नाड़ियाँ सर में","से गुज़रतीं हैं - यह विराट का है।"]],[3212,["प्रीमोर्डियल मास्टर जिसे कहते हैं, प्रीमॉर्डिअल बीइंग,","यह पूरी तरह प्रीमॉर्डिअल बीइंग हैं और इसके अन्दर","आप लोग छोटे छोटे पेशियाँ हैं इसके ऊपर।"]],[3223,["जिसको कि अंग्रेजी में माइंड कहते हैं (अस्पष्ट) यह वो","बड़ा तार जो है परमात्मा ने उसके अन्दर डाल कर","के उसको भी (अस्पष्ट - झंकृत?) किया हुआ है।"]],[3232,["जब ये पेशियाँ जागृत हो जातीं हैं, तब यह","विशाल देह भी जागृत हो जाती है।"]],[3237,["परमात्मा या देवी का अवतरण, जिसने आपको","बनाया हुआ है, आपको मनुष्य बनाया है, और","अब आप उसको जानोगे।"]],[3244,["बुद्धि में पाया, और पाया है। यही आपका","पुनर्जन्म है। यही आपको बनाने वाला है और"]],[3252,["यह चक्र इसलिए बहुत ही महत्वपूर्ण है","सहज योग की दृष्टि से विशेषकर।"]],[3256,["इस विशुद्धि चक्र में सारा ही श्री कृष्ण का स्थान है।","श्री कृष्ण को हम अभी समझ नहीं पाते क्योंकि","परमेश्वर हैं।"]],[3265,["श्री कृष्ण कितने भारी डिप्लोमैट थे मतलब, उनसे","सीखना हो तो राजकारण सीखें और डिप्लोमेसी।"]],[3275,["सारी गीता उनकी डिप्लोमेसी है","यह आप समझ सकते हैं।"]],[3279,["आपने क्योंकि वह इतने बड़े डिप्लोमेट थे कि उन्होंने","सोचा कि यह बेफ़कूफ हैं इन बेवकूफों के आगे","(अस्पष्ट)"]],[3285,["सीधे हाथ आने नहीं वाले।सीधे हाथ ऊँगली","उनके घी नहीं निकलने वाला -","उन्होंने आपको गोल घुमा के बात बताई है"]],[3291,["इसको मैं आपको थोड़े में संक्षिप्त में","बताऊँगी क्योंकि काफी चीज़ें हैं बताने के लिए।"]],[3296,["गीता में कृष्ण ने पहले तो आपको बता ही दिया","कि उसको पाओ, उसको जानो, उसके लिए (अस्पष्ट)।"]],[3305,["आप बस ख़ुद को पाओ, अपने शाँत चित्त में जानो,","अपने से ऊपर लोगों को जानो - पहले चैप्टर में"]],[3314,["यह भी अति क्योंकि वो (अस्पष्ट) समझ लेता तो","उसको कहा कि, \"तुम तो कह रहे अपने को जानो,","उधर कह रहे युद्ध करो, मुझे समझ नहीं आ रहा।\""]],[3324,["उनका मतलब यह था कि, जब आप साक्षी स्वरुप","हो गए तब क्या (अस्पष्ट - नीति?) और क्या","(अस्पष्ट)।"]],[3330,["लेकिन जब अर्जुन ने ऐसा सवाल किया तो एक पिता","के स्वरुप उन्होंने बड़े उसके साथ डिप्लोमेसी की है","जो आपके साथ भी (अस्पष्ट - करना चाहिए?)।"]],[3337,["हम तो माँ हैं इस कर के साफ़ साफ़ बात बता रहे हैं","कि आपको बुद्धू बना रहे हैं क्योंकि आप बुद्धू","बनना चाहते हैं तो फिर क्या?"]],[3343,["पिता का तरीका और होता है, माँ का तरीका और।","उन्होंने इस तरह से आपको बेवक़ूफ़ बनाया कि","जैसे कि समझ लीजिये कि एक बेटा है,"]],[3355,["और वह गाड़ी पर बैठा है और उसको हाँकना चाहता","है और घोड़ा पीछे है, तो बाप ने आ के कहा कि,"]],[3361,["\"बेटे घोड़े को आगे कर ले तभी तेरा काम चलेगा,","तभी तेरी गाड़ी चलेगी।\" तो बेटे ने कहा कि,","\"नहीं, उसको पीछे रख के मैं करूँगा।\""]],[3368,["तो बाप ने उसको आ के समझाया, वो नहीं समझा, तो","कहा कि, \"अच्छा, तुम हाँकते रहो सारा हाँकते रहना","लेकिन चित्त घोड़े पे रखना।\""]],[3377,["जो उन्होंने कह दिया आपसे वह था","चित्त पे आत्मा देना।"]],[3382,["जो कुछ कर्म करवा दिए कर दिए होंगे कि एक","दशा तक पहुँच जाएँ। बड़ा भारी चक्कर है (अस्पष्ट)"]],[3387,["के कर्म करते रहो और सारा बोझा परमात्मा","पे रखते रहो। यह हो ही नहीं सकता।"]],[3391,["ये डिप्लोमेसी, कि एब्सर्ड कंडीशंस डाल दो -","एब्सर्ड कंडीशंस। अगर आप ये सोचते हों कि","हम जो भी करें बड़े कर्मयोगी हैं,"]],[3399,["परमात्मा को छोड़ें इसका आपका कोई भरोसा नहीं","है। करते रहिए। आपका कभी भी नहीं हो सकता","क्योंकि आपका उल्लू बना के रख दिया।"]],[3407,["जब तक आपका योग न हुआ है आप कोई सा भी काम","करेंगे कभी भी यह नहीं सोचते कि उसका कोई फल","आपको मिला है।"]],[3414,["जब आप पार हो जाएँगे तब आप दूसरी तरह की","भाषा बोलते हैं 'हो रहा है' या 'आ रहा है'।"]],[3421,["तीसरी भाषा बोलते हैं 'ये उठ रहा है, ये चल","रहा है' , 'कुण्डलिनी उठ रही, ये पार हो गए'।"]],[3427,["आपका अपना बेटा भी होगा तब भी कहेंगे,","\"माँ क्या करें ये पार नहीं हो सकता।\""]],[3432,["जो होते हैं वो होते हैं, नहीं होते तो नहीं होते।","'कर्मण्ये वाधिका रस्ते फलेषु महा कदाचिन'।"]],[3437,["ये सारा सहज योग में (अस्पष्ट) करते हैं कि","कर्म हम देखिये हम ये कुण्डलिनी उठा रहे।"]],[3442,["ऊपर तक लाये, फिर गिर गई कुण्डलिनी। अब हम","क्या करें? अगर कुण्डलिनी ठहरती नहीं तो","हम क्या करें ?"]],[3448,["फलेषु कदाचिन। कर्म अब आप परमात्मा पे","छोड़िए क्योंकि होता ही है। होने का सवाल ही","नहीं हो ही नहीं सकता।"]],[3448,["फलेषु कदाचिन। कर्म अब आप परमात्मा पे","छोड़िए क्योंकि होता ही है। होने का सवाल ही","नहीं हो ही नहीं सकता।"]],[3458,["आप अकर्म में आ गए। आपके हाथ से चीज़ बह","रही। सूर्य हैं, वो अकर्म में बैठे हैं, उनसे आ रहा है"]],[3466,["प्रकाश जिसे सारी धरती में आप देख रहे हैं","कि हरियाली छाई हुई है।"]],[3470,["एक एक पत्ते पत्ते में हरियाली कर रहे हैं लेकिन","अकर्म में हैं वह भी। इनैक्टिवेली एक्टिव हैं।"]],[3478,["ख़ुदी इनएक्टिव हैं अंदर से और एक्टिव। अपनी","एक्टिविटी देखते हैं और इनैक्टिविटी से रिहा","कर रहें हैं।"]],[3486,["यह सिर्फ पार होने के बाद हो सकता है लेकिन","जब (अस्पष्ट) हो गए। भागते रहो (अस्पष्ट)"]],[3493,["पर माँ की और बात। उसने कहा, \"बेटा","भागते भागते थक गया है\"।"]],[3498,["(अस्पष्ट) ये तो मैं कहूँगी (अस्पष्ट)","ये फर्क होता है"]],[3507,["तो भी (अस्पष्ट) क्या करें ? वो बात कुछ है","(अस्पष्ट)"]],[3516,["भक्ति योग में भी, भक्ति योग में भी यही है।","भक्ति योग में कहते हैं पुष्पम, फलम, तोयम -"]],[3526,["पुष्प, फ़ल और पानी जो भी हमें दोगे हम उसे","स्वीकार्य करेंगे, लेकिन आप क्या दीजियेगा"]],[3532,["तो उसमे कह देते हैं कि [अस्पष्ट] - ये बड़ा भारी है","देखिये, उन्होंने जो कमाल का एक वर्ड इस्तेमाल","किया है, उसपे किसी का ध्यान नहीं गया है,"]],[3541,["सब लोग गीता का प्रवचन सुन रहे हैं","(अस्पष्ट)"]],[3545,["एक बड़ा ही अच्छा शब्द है जो कि आपकी समझ में","नहीं आया। उनका यही तो कमाल है?","लेकिन 'अनन्य भक्ति करो'."]],[3552,["ये शब्द (अस्पष्ट) अनन्य का मतलब क्या ?","जब दूसरा कोई नहीं होगा। माने, आप पार","हो गए तभी तो होगा।"]],[3559,["ये पकड़ है। अनन्य भक्ति करो। अनन्य कैसे करें?","जब तक आप पार नहीं होंगे आप कर ही नहीं सकते।"]],[3567,["अब्सर्ड कंडीशन डाल देना चाहिए, ये डिप्लोमेसी है।","ये है। कोई भी चीज़ ऐसी करो कि जिसकी अब्सर्ड","कंडीशन हो, दूसरा चक्कर में आ जायेगा।"]],[3577,["जब तक अनन्य भक्ति नहीं होएगी आपकी भक्ति","ही नहीं। अनन्य हो नहीं सकती जब तक आप","पार नहीं होते।"]],[3583,["मतलब आपके देने का है, कि हाँ, आप पार","हो जाइये। ये इसका पॉइंट है।"]],[3589,["अगर आप समझ लें कि गीता में भी कृष्ण","ने सारा सहज योग ही बताया है।"]],[3594,["उन्होंने जो लीला की हुई है इसी लीला में कि","- राधाजी असल में आदिशक्ति थीं -"]],[3599,["वो जब नदी पर से, यमुना  जी से","आतीं थीं, तो सारा पानी विब्रेट हो गया।"]],[3605,["अब जब गोपियाँ वहाँ पानी भरने जातीं थीं, तो कृष्ण","उन्हें कंकण मारते थे। वो जो विब्रेटेड पानी सारा","कुण्डलिनी पे उतरता था धड़ धड़ धड़।"]],[3613,["उससे उठाते थे वह। देखिये उनके कमाल","(अस्पष्ट) थे न बचपन से ही।"]],[3620,["जब गोपियों के - छोटे से थे चार साल के तब -","उन्होंने कपडे छुपा दिए। तब भी उनकी कुण्डलिनी","ऊपर बैठ के जगाते थे"]],[3630,["और देख रहे थे कि कुण्डलिनी कहाँ है, क्या है।","ऐसे लोग तब बैठा करते थे क्या कोई?"]],[3635,["उस ज़माने में कोई ऐसा कहता गोकुल में, \"भैया ऐसे","बैठो\" और लेक्चर दे, तो कोई सुनता (असपष्ट)?"]],[3640,["रास, वो भी यही। 'रा' माने शक्ति और 'स' सहित।","रास, रास का मतलब है 'रा' माने शक्ति थी उसका","हाथ पकड़वा के नचाते।"]],[3650,["नाचते नाचते आदमी थक जाए (अस्पष्ट)","लेकिन फिर नाचे और कुण्डलिनी चढ़ा रहे।"]],[3659,["जब तक उनकी मजबूरी होती थी वो इस","शक्ति को स्तेमाल करते।"]],[3664,["सारा ही उन्होंने सहज योग किया।"]],[3667,["राम भी जब पैर में जूते पहने बगैर","सीताजी को ले गए थे साथ में, वो भी","इसलिए, कि सारा भारतवर्ष","जो है उसको वायब्रेट कर दिया जाए।"]],[3676,["नंगे पैरों से घुमाया, सबको विब्रेट","करा दिया। ये सारा नाटक रचाया हुआ है,","हम लोगों ने जिससे अपनी भूमि","जागृत हो, अपनी भूमि पे चल कर।"]],[3685,["आठ हज़ार(सौ) साल पहले आये। आपको बताने","का आज जब समय आया, जब हम आये तो देखा"]],[3689,["कि आप लोग सब अँगरेज़ हो गए।","अब अंग्रेज़ों का क्या करें?"]],[3695,["वो सारी संवेदना ख़तम हो गईं, वो सारी खूबसूर्तियाँ","ख़तम हो गईं, वो सादगियाँ ख़तम हो गईं,"]],[3703,["वो पवित्रता ख़तम हो गई, अब हम अपना","सर पकड़ के बैठे कि अब क्या करें?"]],[3707,["अब कलश चढाने का टाइम आया","तो ये हालत आपने अपनी कर ली।"]],[3712,["अभी भी परमात्मा की कृपा से अपने देहातों में","काफी अच्छी तरह सादगी है और आप लोग भी"]],[3718,["अगर इस चीज़ को समझ लें और इसमें जमें,","तो सहज योग बहुत अच्छे से जम सकता है।"]],[3725,["एक बात (अस्पष्ट) करते ही साथ, आपको आश्चर्य","होगा, कि किस तरह से सारा ही हवा का रूख।"]],[3735,["अब अगर पूछा कि कम्युनिज्म अच्छा है कि","डेमोक्रेसी? कैपिटलिज्म अच्छा है, कि कम्युनिज्म","अच्छा है (अस्पष्ट)?"]],[3747,["मैंने कहा ये सबसे बड़ा कैपिटलिज्म तो पहले","हुआ कि सारी आपकी शक्ति जागृत हो गई,","आपकी सारी ख़ुद की सम्पदा।"]],[3752,["और दिए बगैर आपको चैन नहीं आता ये सबसे बड़ा","कम्युनिज्म हुआ। आपको दिए बगैर चैन ही नहीं","आने वाला यह आपका कम्युनिज्म है।"]],[3759,["और दोनों चीज़ें आगे जाकर वहीँ","सहज योग में मिलीं।"]],[3763,["इसमें तो मज़ा इसी में आता है","कि आप देते रहो। फिर ये नहीं मज़ा आता है","कि आपके पास रुपया कितना जुटा है,","आपके पास सामान कितना जुटा है"]],[3770,["आपके पास चीज़ें कितनी जुटीं हैं, पर ये आता","है कि कितनों को आपने पार कराया ?"]],[3776,["इसी में मज़ा आता है, इसी में जुटा रहता है,","बहाने में और देने में और अपना संचय करता","रहता है ध्यान धारणा से।"]],[3784,["सारा ही इंसान की पूरी तबियत बदल जाती है,","ऊपर से नीचे तक क्योंकि एक यह जीवंत चीज़ है।"]],[3791,["जिस तरह एक पेड़ अगर ख़राब हो जाये,","तो उसको मनुष्य ठीक कर सकता है,"]],[3795,["लेकिन अगर इसका ऊपर का (अस्पष्ट- ग्लोब)","समझ लीजिये अगर पाया","ख़राब हो जाये, तो आप इसे ठीक","नहीं कर सकते हैं।"]],[3802,["पर एक पेड़ को आप ठीक कर सकते हैं क्योंकि आप","जीवंत हैं; आपको लेकिन इसको पूरी तरह से"]],[3807,["समझ लेना चाहिए और जो महत्वपूर्ण है उसे पकड़","लेना चाहिए। फ़ालतू की चीज़ों में अपना समय","बर्बाद नहीं करना चाहिए।"]],[3813,["आज ही एक देवीजी आईं थीं, उनकी तबियत","इतनी ख़राब। मैंने कहा, \"आप करती क्या हैं?\"","कहने लगीं, \"उपास।\""]],[3818,["हमने कहा, \"दिमाग ख़राब है?\" अच्छी भली गयीं थी","भगवन ने सारा बनाया उपास करने की क्या बात है?"]],[3823,["कोई बीमार पड़ते हैं अधिक खाने से और कोई पड़ते हैं","उपास से। अरे, इसमें रखा क्या है? एक बीचों बीच","रहो। कोई अतिशयता पे न हो।"]],[3832,["कोई धर्मातीत गुणातीत आप उठ जाएँगे और फिर","कुण्डलिनी जब विशुद्धि चक्र से लांघ कर के","आज्ञा चक्र में पहुँचेगी,"]],[3838,["तब आपको पता होगा कि आप निर्विचारिता","में चले जा रहे हैं।"]],[3843,["आज काफी मैंने भाषण दिया है और आप जानते हैं","कि, दो तीन महीने से लगातार तीन-तीन, चार-चार","बार मैं भाषण कर रही हूँ।"]],[3853,["और बहुत ही सफल विद्या। कल तो यहाँ नहीं है","प्रोग्राम पर शाम को मैं कोशिश करुँगी इसलिए","कि मैं पूरा इन चक्रों के बारे में बताऊँगी"]],[3860,["और सहज योग से क्या लाभ होते हैं,","इसके बारे में भी शाम को बताऊँगी।"]],[3865,["आशा है आप लोग सब आयेंगे। थोड़ी देर हम लोगों को","ध्यान करना चाहिए क्योंकि ध्यान में ही उपलब्धि","होती है"]],[3871,["और उपलब्धि में ही सारे इसका मुख्य कारण है","और मुख्य हेतु है बाकी सब ठीक है।"]],[3877,["हाँलाँकि भाषण से भी आपकी कुण्डलिनी थोड़ी","सी ऊपर जाती है और इसीलिए हम इसे करते हैं"]],[3882,["और आशा है कि आप इसे पाइएगा और पाने के बाद","इसमें जमिए - यह नहीं कि दो मिनिट को आये","और चले गए - यह कोई सिनेमा का शो नहीं है,"]],[3890,["या कोई नाटक नहीं है, या कोई ऐसी चीज़ नहीं है कि","आप गए और चले गए - इसमें जमना पड़ता है।"]],[3896,["आप ख़ुद इसमें एक्टर हैं। एक्टर को एक बार शो","करने से नहीं होता। आप खुद स्टेज पर हैं।"]],[3903,["स्टेज पूरा आपके लिए तैयार किया हुआ है।","आप आईये और एक्टिंग करिये।"]],[3907,["ये नहीं कि आप जो आये देखा, अच्छा भला कहा और","चल दिए। आप खुद स्टेज पे उतरिये और काम करिए।"]],[3919,["आज के भाषण के बाद शाम के लिए","(अस्पष्ट - ध्यान होगा ५ बजे?) से","और ७ बजे तक हम ख़तम कर देंगे"]],[3927,["क्योंकि यहाँ से जाने के लिए मेरे को काफी","(अस्पष्ट - समय लगेगा ?)"]],[3931,["हाँलाँकि हम तो घडी वडी बाँधते नहीं और खास","तौर इस तरफ ध्यान नहीं देते हमेशा उलटी","चलती रहती हमारी घडी"]],[3937,["और ये हमारा सारा जो है (अस्पष्ट)","चलते रहता है उनके काम कर कर के।"]],[3941,["काफी मस्त मौला हैं क्या करें। उसी तरह से सब","काम होते रहते हैं और इस तरह से काम बनते हैं।"]],[3947,["इसलिए हमको माफ़ कर देना चाहिए अगर हम कभी","देर से आयें तो वो ज़रूरी होता है क्योंकि देर से","इसका मुहूर्त होता है।"]],[3952,["हमारा बड़ा मुहूर्त से काम होता है। एक अभी हम जिस","(अस्पष्ट) में थे - एक तो प्रोग्राम भी हमारे","पचासों रहते हैं।"]],[3959,["ये तो कहने लगे साहब, एक साहब हैं, \"वहाँ","बड़ी अच्छी ज़मीन है समुद्र के किनारे, वहाँ माताजी","बड़ा अच्छा रहेगा बस लेकिन एक बार देख लीजिये।\""]],[3965,["और उसी दिन एक साहब ने पूजा रखी कि पूजा में","आओ माने उस दिन उनका बर्थडे और बहुत प्रोग्राम थे।"]],[3971,["और वो ले गए कहीं साब समुन्दर के पास। वहाँ","चलते चलते तीन चार मील हमारी कुछ कुछ टांगें","तो उनने तोड़ीं,"]],[3977,["और उसके बाद अब वापस आने में बहुत देर हो गई।","हम तो आराम से आये थे। कहने लगे आये तो","सब लोग बैठे थे २ बज गया। ढाई बजे पूजा शुरू हुई।"]],[3986,["तो सबने कहा, \"माताजी, ढाई बजे पूजा हो रही अब","खाना कब होएगा?\" मैंने कहा, \"खाने का एक दिन नहीं","हुआ तो क्या हुआ, कौन सी आफत आ गई।\""]],[3992,["मैंने कहा, \"अच्छा, ये तो पता लगाओ कि तुम्हारा","खुद जनम कब हुआ?\" तो कहे, \"ये तो पता नहीं।\"","हमने कहा, \"ज़रा पता करो।\""]],[3997,["ढाई बजे तुम्हारा जनम हुआ था इसीलिए ढाई बजे","पूजा करी। और पता लगाया कि ढाई बजे का है।"]],[4002,["तो सारा कुछ पंचांग हम ले के चलते हैं। और वो","पंचांग ऐसा बनता है के बराबर ठीक रहता है।"]],[4008,["अभी एक (अस्पष्ट) ने पूछा कि (अस्पष्ट)"]],[4019,["उस दिन अमावस्या है ऐ [नवमी है] हाँ नवमी है।","हाँ, तो उन्होंने कहा कि, \"सवेरे से हवन शुरू करिए।\""]],[4027,["हमने कहा, \"हाँ, हाँ करेंगे, करेंगे,\" ऐसे टालते रहे,","टालते रहे। करते करते चार बजा दिए।"]],[4033,["तो उन्होंने कहा कि, \"माताजी हम तो सवेरे","से हवन करने की सोच रहे।\""]],[4038,["मैंने कहा, \"क्या है, तुम लोग तो ध्यान करोगे,","ध्यान करलो, आज के दिन ऐसा भी क्या आफ़त है।\""]],[4042,["फिर मैंने कहा, \"अच्छा ज़रा पता लगाओ नवमी","कितने बजे चढ़ी?\" क्योंकि नवमी का करने","का विचार था।"]],[4047,["तो कहने लगे, \"चार बजे से।\" मैंने कहा, \"देखो तो ज़रा\"","हम तो कोई विल प्लान नहीं। हम को कहो कोई पंचांग","पढ़ें, हम नहीं जानते।"]],[4053,["लेकिन सब हमारा पंचांग अपना बना रहता,","हम अपने पंचांग से चलते और तुम लोगों","को भी यह सीखना चाहिए।"]],[4058,["बहुत ज़्यादा संकल्प करोगे तो 'संकल्प विकल्प","करोति'। ऐसे लोग चोट खाते हैं और फिर लोग कहने","लग जाते हैं कि , \"माताजी, देखो हमारा ये ....।\""]]]);
